7	const STEPS = [
8	  { label: 'Loading emails from Gmail...', endpoint: '/api/emails/fetch' },
9	  { label: 'Classifying messages...', endpoint: '/api/ai/classify' },
10	  { label: 'Parsing rate requests...', endpoint: '/api/ai/parse-request' },
11	  { label: 'Building negotiation recaps...', endpoint: '/api/ai/recap' },
12	];
13	
14	type StepStatus = 'pending' | 'loading' | 'done' | 'error';
15	
16	export function ProgressProcessing() {
17	  const [statuses, setStatuses] = useState<StepStatus[]>(STEPS.map(() => 'pending'));
18	  const [error, setError] = useState<string | null>(null);
19	
20	  useEffect(() => {
21	    async function runPipeline() {
22	      for (let i = 0; i < STEPS.length; i++) {
23	        setStatuses(prev => prev.map((s, idx) => idx === i ? 'loading' : s));
24	        try {
25	          const res = await fetch(STEPS[i].endpoint, { method: 'POST' });
26	          if (!res.ok) {
27	            const data = await res.json().catch(() => ({}));
28	            throw new Error(data.error || `Step ${i + 1} failed`);
29	          }
30	          setStatuses(prev => prev.map((s, idx) => idx === i ? 'done' : s));
31	        } catch (err) {
32	          setStatuses(prev => prev.map((s, idx) => idx === i ? 'error' : s));
33	          setError(err instanceof Error ? err.message : 'Processing failed');
34	          return;
35	        }
36	      }
37	      window.location.href = '/dashboard';
38	    }
39	    runPipeline();
